CREATE TABLE IF NOT EXISTS wishlists (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS product_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), product_id uuid NOT NULL REFERENCES products(id), order_item_id uuid UNIQUE NOT NULL REFERENCES order_items(id), rating integer NOT NULL CHECK(rating between 1 and 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), store_id uuid NOT NULL REFERENCES stores(id), suborder_id uuid UNIQUE NOT NULL REFERENCES suborders(id), rating integer NOT NULL CHECK(rating between 1 and 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, audience text NOT NULL CHECK(audience IN ('customer','vendor','admin','delivery_office')), title text NOT NULL, body text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
